export function getLineById(id: string | undefined | null): TransitLine | undefined {
  return TRANSIT_LINES.find((l) => l.id === id);
}

export function lineCoordinates(line: TransitLine): { lat: number; lng: number }[] {
  // Prefer the real GTFS shape when available; fall back to straight
  // stop-to-stop segments for hand-written lines without shapes.
  if (line.shapes && line.shapes.length > 0) {
    return line.shapes.flat();
  }
  return line.stopIds.map((id) => {
    const stop = getStopById(id);
    return { lat: stop.lat, lng: stop.lng };
  });
}

/** All shape polylines for a line (usually inbound + outbound). */
export function lineShapePolylines(line: TransitLine): { lat: number; lng: number }[][] {
  if (line.shapes && line.shapes.length > 0) return line.shapes;
  return [lineCoordinates(line)];
}

